const Hapi = require('@hapi/hapi');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const server = Hapi.server({ port: 4400 });

const verifyWorkspaceActive = async (request, h) => {
  const workspace = await prisma.workspace.findUnique({
    where: { id: request.params.workspaceId }
  });

  if (!workspace || workspace.status !== 'ACTIVE') {
    return h.response({ error: 'Workspace inactive or unavailable' }).code(400).takeover();
  }
  return h.continue;
};

server.route({
  method: 'POST',
  path: '/api/workspaces/{workspaceId}/channels/{channelId}/archive',
  options: {
    auth: 'jwt',
    ext: {
      onPreHandler: { method: verifyWorkspaceActive }
    }
  },
  handler: async (request, h) => {
    const { workspaceId, channelId } = request.params;
    const userId = request.auth.credentials.userId;

    // Verify user is an admin of the target workspace
    const membership = await prisma.workspaceMember.findFirst({
      where: { workspaceId, userId, role: 'ADMIN' }
    });

    if (!membership) {
      return h.response({ error: 'Forbidden: workspace admin role required' }).code(403);
    }

    // Ensure channel belongs to the specified workspace
    const channel = await prisma.channel.findFirst({
      where: { id: channelId, workspaceId }
    });

    if (!channel) {
      return h.response({ error: 'Channel not found in this workspace' }).code(404);
    }

    const archivedChannel = await prisma.channel.update({
      where: { id: channelId },
      data: { isArchived: true, archivedAt: new Date() }
    });

    return h.response({ success: true, channel: archivedChannel }).code(200);
  }
});
